func TestDetectCycles(t *testing.T) {
	graph := NewDependencyGraph()
	// Ciclo: A -> B -> C -> A
	graph.AddEdge("pkgA", "pkgB")
	graph.AddEdge("pkgB", "pkgC")
	graph.AddEdge("pkgC", "pkgA")

	cycles := DetectCycles(graph)
