func (c CommitRef) Key() string {
	if c.Commit == "" || c.Commit == "HEAD" {
		return fmt.Sprintf("%s/%s", c.Owner, c.Repo)
	}
	return fmt.Sprintf("%s/%s@%s", c.Owner, c.Repo, c.Commit)
}

